package com.yinfires.icecore.worldmap;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class MapRulesTest {
    static MapDefinition map(){var d=new MapDefinition();d.minX=-512;d.minZ=-512;d.maxX=512;d.maxZ=512;return d;}
    static MapDefinition.Region square(String id,int x,int z,int size){var r=new MapDefinition.Region();r.id=id;r.polygons.add(List.of(new MapDefinition.Point(x,z),new MapDefinition.Point(x+size,z),new MapDefinition.Point(x+size,z+size),new MapDefinition.Point(x,z+size)));return r;}
    @Test void polygonsAndDisjointSmallIslandsSurviveRoundTrip(){var d=map();var r=square("main",0,0,32);r.runs=new int[]{-200,-200,1,80,100,2};d.regions.add(r);var copy=MapDefinition.parse(MapDefinition.JSON.toJson(d));assertTrue(copy.region("main").contains(-199.5,-199.5));assertTrue(copy.region("main").contains(81.5,100.5));assertFalse(copy.region("main").contains(70,70));}
    @Test void invalidDefinitionsAreRejected(){var d=map();d.regions.add(square("a",0,0,10));d.regions.add(square("a",20,20,10));assertThrows(IllegalArgumentException.class,d::validate);d.regions.remove(1);d.regions.get(0).feather=0;assertThrows(IllegalArgumentException.class,d::validate);d.regions.get(0).feather=64;d.regions.get(0).polygons.set(0,List.of(new MapDefinition.Point(Double.NaN,0),new MapDefinition.Point(1,0),new MapDefinition.Point(1,1)));assertThrows(IllegalArgumentException.class,d::validate);}
    @Test void negativeTileCoordinatesAndMouseZoomStayConsistent(){var v=new MapViewport();v.resize(800,600,new double[]{-1000,-800,600,400},true);double x=v.worldX(300),z=v.worldZ(200);v.zoom(4,300,200);assertEquals(x,v.worldX(300),1e-8);assertEquals(z,v.worldZ(200),1e-8);v.zoom(-100,300,200);assertEquals(v.minimum(),v.scale,1e-12);assertEquals(-200,v.x,1e-8);}
    @Test void draggingCannotEscapeUnlockedBounds(){var v=new MapViewport();v.resize(800,600,new double[]{0,0,1000,1000},true);v.zoom(10,400,300);v.drag(1e9,-1e9);assertTrue(v.worldX(0)>=-1e-8);assertTrue(v.worldZ(600)<=1000+1e-8);}
    @Test void emptyUnlocksHaveNoNavigationBounds(){var d=map();d.regions.add(square("a",0,0,10));assertNull(d.bounds(Set.of(),false));assertArrayEquals(new double[]{-512,-512,512,512},d.bounds(Set.of(),true));var v=new MapViewport();v.resize(800,600,null,true);v.drag(100,100);v.zoom(5,100,100);assertEquals(1,v.scale);}
    @Test void boundsFollowDrawnOuterEdgeAndProjectionPadding(){var d=map();var r=square("a",0,0,10);r.runs=new int[]{-200,-200,1};d.regions.add(r);assertArrayEquals(new double[]{-264,-264,10,10},d.bounds(Set.of("a"),false));}
    @Test void exactInwardDistanceMatchesRectangleReference(){var d=map();d.regions.add(square("a",0,0,256));var f=MapFog.build(d,Set.of("a"));for(double z=.3;z<256;z+=7.1)for(double x=.2;x<256;x+=5.7){double depth=Math.min(Math.min(x,z),Math.min(256-x,256-z));assertEquals(255-(int)Math.round(255*MapFog.smooth(depth/64)),f.alpha(x,z));}}
    @Test void fogStartsAtContourAndFadesOnlyInward(){var d=map();d.regions.add(square("a",0,0,256));var f=MapFog.build(d,Set.of("a"));assertEquals(255,f.alpha(-1,128));assertEquals(255,f.alpha(0,128));assertEquals(0,f.alpha(128,128));assertEquals(255,f.alpha(257,128));int last=255;for(int x=0;x<=64;x++){int alpha=f.alpha(x,128);assertTrue(alpha<=last,"inward fade at "+x);last=alpha;}assertEquals(127,f.alpha(32,128));}
    @Test void lockedIslandIsProtectedFromNeighbourExpansion(){var d=map();d.regions.add(square("a",0,0,32));d.regions.add(square("locked",70,0,8));var f=MapFog.build(d,Set.of("a"));assertEquals(255,f.alpha(74,4));assertEquals(0,f.alpha(16,16));}
    @Test void lockedShorelineIsFullyOpaqueEvenAtSubpixelBoundary(){var d=map();d.regions.add(square("a",0,0,32));d.regions.add(square("locked",70,0,8));var f=MapFog.build(d,Set.of("a"));for(double x:new double[]{70.001,70.5,77.999})for(double z:new double[]{.001,4,7.999})assertEquals(255,f.alpha(x,z));}
    @Test void singleBlockIslandSurvivesCoarseDistanceField(){var d=map();d.minX=-8192;d.minZ=-8192;d.maxX=8192;d.maxZ=8192;var r=new MapDefinition.Region();r.id="tiny";r.runs=new int[]{-200,-200,1};d.regions.add(r);assertEquals(0,MapFog.build(d,Set.of("tiny")).alpha(-199.5,-199.5));}
    @Test void unlockRemovesProtectionAndSinglePixelIslandIsNeverFiltered(){var d=map();var r=new MapDefinition.Region();r.id="tiny";r.runs=new int[]{-200,-200,1};d.regions.add(r);assertEquals(0,MapFog.build(d,Set.of("tiny")).alpha(-199.5,-199.5));assertEquals(255,MapFog.build(d,Set.of()).alpha(-199.5,-199.5));}
    @Test void smoothstepHasFlatEndpoints(){assertEquals(0,MapFog.smooth(-1));assertEquals(1,MapFog.smooth(2));assertEquals(.5,MapFog.smooth(.5));assertTrue(MapFog.smooth(.001)<.000004);assertTrue(1-MapFog.smooth(.999)<.000004);}
    @Test void sharedStateIsIdempotentAndPersists(){var d=new MapSavedData();assertTrue(d.change("a",true));assertFalse(d.change("a",true));assertEquals(1,d.revision);var restored=MapSavedData.load(d.save(new net.minecraft.nbt.CompoundTag()));assertEquals(Set.of("a"),restored.unlocked);assertTrue(restored.change("a",false));assertFalse(restored.change("a",false));assertEquals(2,restored.revision);}
}
